import org.eclipse.rdf4j.workbench.util.TupleResultBuilder;
import org.eclipse.rdf4j.workbench.util.WorkbenchTupleResultWriter;
import org.junit.jupiter.api.Test;

class SummaryServletTest {

	@Test
	void serviceEmitsEffectiveConfigMetadataAsPrettyPrintedTurtle() throws Exception {
		SummaryServlet servlet = new SummaryServlet();
		RepositoryManager manager = mock(RepositoryManager.class);
		Repository repository = mock(Repository.class);
		RepositoryConnection connection = mock(RepositoryConnection.class);
		RepositoryInfo info = new RepositoryInfo();
		info.setId("memory");
		info.setDescription("Memory repo");

		when(manager.getRepositoryConfig("memory")).thenReturn(repositoryConfig());
		when(repository.getValueFactory()).thenReturn(SimpleValueFactory.getInstance());
		when(repository.getConnection()).thenReturn(connection);
		when(connection.size()).thenReturn(7L);
		when(connection.getContextIDs()).thenReturn(repositoryResultOf(
				SimpleValueFactory.getInstance().createIRI("urn:test:ctx")));

		servlet.setRepositoryManager(manager);
		servlet.setRepository(repository);
		servlet.setRepositoryInfo(info);

		ByteArrayOutputStream buffer = new ByteArrayOutputStream();
		TupleResultBuilder builder = new TupleResultBuilder(new WorkbenchTupleResultWriter(buffer),
				SimpleValueFactory.getInstance());

		servlet.service(builder);

		String xml = buffer.toString(StandardCharsets.UTF_8);

		assertThat(xml)
				.contains("<workbench:config-model-turtle>")
				.contains("@prefix config:")
				.contains("@prefix rdfs:")
				.contains("config:rep.id \"memory\"")
				.contains("config:rep.impl [")
				.contains("config:sail.impl [")
				.contains("config:mem.persist true")
				.doesNotContain("_:");
	}

	private static RepositoryConfig repositoryConfig() {
		MemoryStoreConfig memoryStoreConfig = new MemoryStoreConfig(true, 123L);
		return new RepositoryConfig("memory", "Memory repo", new SailRepositoryConfig(memoryStoreConfig));
	}

	private static RepositoryResult<Resource> repositoryResultOf(Resource... resources) {
		return new RepositoryResult<>(new CloseableIteratorIteration<>(List.of(resources).iterator()));
	}
}
